css:
/* Luna-inspired interface. Original rolling-hills illustration, not Bliss. */
[data-skin-part="shell"] { background: #458bdd url("skin:hills") center / cover; }
[data-skin-part="main"], [data-skin-part="sidebar"] { border: 3px solid #0b51d5; border-radius: 8px 8px 0 0; box-shadow: 2px 3px 8px #17366366; overflow: hidden; }
[data-skin-part="header"], .side__heading { background: linear-gradient(#4a99ff, #0864e9 12%, #0054d5 80%, #0645b5); color: #ffffff; border-bottom: 1px solid #003da7; text-shadow: 1px 1px #163f8c; }
.pane-head__title, .side__title { font-family: 'Trebuchet MS', 'Tahoma', sans-serif; font-weight: 700; }
.side__head { background: linear-gradient(#ffffff, #ece9d8); padding: 0 12px 12px; }
.side__heading { margin: 0 -12px 12px; padding: 8px 12px; }
[data-skin-part="header"] .btn, .side__heading .btn, .side__heading a { color: #ffffff; background: #216ce0; border-color: #8fbdfb; }
[data-skin-part="header"] .dim { color: #e1efff; }
[data-skin-part="navigation"] { background: linear-gradient(#4696ff, #2462db 16%, #245edb 80%, #1941a5); border: 0; box-shadow: inset 0 2px #8ec2ff; }
.rail__item { color: #ffffff; border-radius: 3px; text-shadow: 1px 1px #1949a2; }
.rail__item:hover { color: #ffffff; background: #4185ef; }
.rail__item--active { color: #ffffff; background: #174cb4; box-shadow: inset 1px 1px 3px #082e86; }
.rail__item--active::before { display: none; }
.rail__brand { background: linear-gradient(#7dcc76, #3b9832 25%, #2b7e24 80%, #22621e); color: white; box-shadow: inset 0 2px 3px #c2f4ba; border-radius: 0 12px 12px 0; }
.rail__brand .brand-mark { color: white; }
.btn, .pick { background: linear-gradient(#ffffff, #f2f0e6 65%, #dedbca); border: 1px solid #71849a; border-radius: 3px; box-shadow: inset 1px 1px #ffffff; color: #18243a; }
.btn:hover, .pick:hover { border-color: #1c61bd; box-shadow: inset 0 0 0 2px #f4c65a; }
.btn--primary { background: linear-gradient(#568ef0, #1b56c0); color: #ffffff; border-color: #12499e; }
.field, .side__search, [data-skin-part="composer"] { background: #ffffff; border: 1px solid #7f9db9; box-shadow: inset 1px 1px 2px #b7bcc5; }
[data-skin-part="composer"] { border-radius: 3px; }
.composer__bar, .composer__configuration { background: #ece9d8; }
.composer__send::before { clip-path: none; background: linear-gradient(#74bd60, #328828); border: 1px solid #28721d; border-radius: 3px; }
.composer__send:disabled::before { background: #cbd1c4; border-color: #8a9784; }
[data-skin-part="conversation"], [data-skin-part="welcome"] { background: linear-gradient(#ffffff, #f4f1e6); }
[data-skin-part="message"][data-role="assistant"] .bubble { padding: 14px; background: #ffffff; border: 1px solid #b9c9dc; border-radius: 3px; box-shadow: 2px 2px 0 #e3e0d3; }
[data-skin-part="message"][data-role="user"] .bubble { border: 1px solid #7eace5; border-radius: 3px; box-shadow: 2px 2px 0 #d9e3f0; }
.row-item--active { background: #316ac5; color: #ffffff; border-radius: 2px; }
.row-item--active .row-item__title, .row-item--active .row-item__sub, .row-item--active .dim, .row-item--active .row-item__time { color: #ffffff; }
.settings__title, .welcome__title { color: #174db0; font-family: 'Trebuchet MS', 'Tahoma', sans-serif; }
@media (min-width: 901px) {
  [data-skin-part="shell"] { grid-template-columns: auto minmax(0, 1fr); grid-template-rows: minmax(0, 1fr) 3rem; padding: 12px 12px 0; gap: 10px; }
  [data-skin-part="shell"].shell--full, [data-skin-part="shell"].shell--collapsed { grid-template-columns: minmax(0, 1fr); }
  [data-skin-part="sidebar"] { grid-column: 1; grid-row: 1; }
  [data-skin-part="main"] { grid-column: 2; grid-row: 1; }
  .shell--full [data-skin-part="main"], .shell--collapsed [data-skin-part="main"] { grid-column: 1; }
  [data-skin-part="navigation"] { grid-column: 1 / -1; grid-row: 2; flex-direction: row; padding: 0; margin: 0 -12px; align-items: stretch; gap: 8px; }
  .rail__brand { width: 6rem; height: auto; margin: 0; display: flex; gap: 8px; justify-content: center; flex-shrink: 0; }
  .rail__brand .brand-mark { width: 1.5rem; height: 1.5rem; }
  .rail__brand::after { content: 'start'; font-style: italic; font-weight: 700; font-size: 1rem; }
  .rail__nav { flex-direction: row; width: auto; flex: 1; gap: 4px; align-items: stretch; padding: 4px 0; }
  .rail__item { flex-direction: row; gap: 8px; min-height: 0; width: auto; padding: 0 16px; border: 1px solid #6197ee; }
  .rail__label { font-size: 0.75rem; }
  .rail__settings { margin: 4px 8px 4px auto; }
}
@media (max-width: 900px) { [data-skin-part="main"], [data-skin-part="sidebar"] { border-width: 2px; border-radius: 0; } }
